script:
frappe.views.calendar["Course Schedule"] = {
    field_map: {
        start: "from_time",
        end: "to_time",
        id: "name",
        title: "course",
        allDay: "all_day"
    },
    get_events_method: "education.education.doctype.course_schedule.course_schedule.get_events",

    // This intercepts the calendar load and injects the instructor restriction
    onload: function(calendar_view) {
        if (frappe.user_roles.includes("Instructor")) {
            // Find the instructor record linked to the current logged-in user
            frappe.db.get_value('Instructor', { user_id: frappe.session.user }, 'name', (r) => {
                if (r && r.name) {
                    // Force the calendar to only fetch events for this instructor
                    calendar_view.filter_vals = { instructor: r.name };
                    calendar_view.refresh();
                }
            });
        }
    }
};

frappe.ui.form.on('School House', {
    refresh: function(frm) {
        if (!frm.is_new()) {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Student",
                    filters: { "custom_falemohe": frm.doc.name },
                    fields: ["name", "first_name", "last_name"]
                },
                callback: function(r) {
                    if (r.message) {
                        frm.clear_table("custom_students"); // Use your actual table field name
                        r.message.forEach(stu => {
                            let child = frm.add_child("custom_students");
                            child.student = stu.name;
                            child.student_name = stu.first_name + " " + (stu.last_name || "");
                        });
                        frm.refresh_field("custom_students");
                    }
                }
            });
        }
    }
});
